item.content:encoded:
img {
    max-width: 100%;
    height: auto !important;
    object-fit: cover; /* Запълва пространството без разтягане */
}

wp:postmeta.wp:meta_value:
.post-meta {
    display: none;
}

ul.social-icon li:nth-child(3) {
    display: none;
}

.one-bullet-list ul li {
    border-bottom: 1px solid lightgray;
}

.img-rotate-scale figure, .img-rotate-scale img {
    transition: 1s all;
    transition-timing-function: cubic-bezier(0.1, 1, 0.6, 0.8);
}

.img-rotate-scale figure:hover {
    transform: scale(1.1);
}

.img-rotate-scale img:hover {
    -ms-transform: rotate(-5deg);
    transform: rotate(-5deg);
}

.fancy-title {
    margin-bottom: 0;
}

.img-icon-container .wpb_single_image {
    display: flex;
    justify-content: center;
    align-items: center;
    margin-top: 10px;
    margin-bottom: 10px;
}

